import {sourceLinks,roadmapInsights} from './journey-view.js';
export {journeyView} from './journey-view.js';
import {DATA,programFor,coursesFor,creditsOf,label} from './planner.js';
import {GUIDED,STEPS,suggestMinors,allowedChoices,planIssues,completedIds} from './guidance.js';
import {minorSummary} from './minor-summary.js';
import {selectedMinor} from './minors.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const source=s=>({file:s?.file||s?.filename||'aui academic catalogue.pdf',page:Math.max(1,Math.min(1000,Number(s?.page||s?.pdfPage||s?.pages?.[0])||1))});
export const cite=(s,text)=>{s=source(s);return `<button type="button" class="source-link" data-source-file="${esc(s.file)}" data-source-page="${s.page}">${esc(text||`${s.file} · p${s.page}`)} ↗</button>`;};
export const link=(url,title)=>/^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`:'';
export const btn=(action,text,primary=false)=>`<button type="button" class="button ${primary?'primary':'secondary'}" data-action="${action}">${text}</button>`;
export const options=(list,value)=>list.map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
const select=(key,title,list,value,kind='journey')=>`<label class="field">${title}<select data-${kind}="${key}">${options(list,value)}</select></label>`;
const field=(key,title,value,type='text',kind='journey')=>`<label class="field">${title}<input type="${type}" data-${kind}="${key}" value="${esc(value)}" ${type==='number'?'step="any"':''}></label>`;
const notes=list=>(list||[]).map(n=>`<p class="small-note">${esc(typeof n==='string'?n:n.text||n.details||JSON.stringify(n))}</p>`).join('');
export function choiceField(c,p){const selected=p.choices[c.id]||'';return `<label class="field choice-field"><span>${esc(c.title)} <small>· ${c.credits} credits</small></span><select data-choice="${esc(c.id)}">${options([['','Choose a course'],...allowedChoices(c,p).map(x=>[x.code,`${x.code} · ${x.title} (${x.credits} cr.)${x.creditsProvisional?' · verify credits':''}`])],selected)}</select>${c.condition?`<small>${esc(c.condition)}</small>`:''}${c.replacementFor?'<small>Advisor-approved replacement required.</small>':''}</label>`;}
export function experienceCards(items=[]){return '<div class="target-grid">'+items.map(t=>`<article class="target-card"><h3>${esc(t.name)}</h3><small>${esc([t.organizationType,t.country].filter(Boolean).join(' · '))}</small><p>${esc(t.reason)}</p><details><summary>Why this fits</summary><p>${esc(t.industryReason||t.tierReason||'')}</p><p class="small-note">${esc((Array.isArray(t.constraints)?t.constraints.join(' '):t.constraints)||t.caveat||'Check current openings, eligibility and dates.')}</p>${link(t.sourceUrl,'Learn more')}</details></article>`).join('')+'</div>';}

function basePlanView(plan,draft){
 const cs=plan.courses,done=completedIds(plan),checks=planIssues(plan),completed=creditsOf(cs.filter(c=>done.includes(c.id))),total=creditsOf(cs),first=plan.terms.find(t=>!['prior','pending'].includes(t.id)&&t.courses.some(id=>!done.includes(id)))?.id;
 return `<section class="plan-banner"><div><span class="eyebrow">${draft?'REVIEW BEFORE SAVING':'YOUR SAVED ROADMAP'}</span><h2>${esc(plan.profile.name?plan.profile.name+'’s next chapter':'Your next chapter')}</h2><p>${esc(plan.program.name)}</p></div><div class="card-actions">${draft?btn('finalize','Save my plan',true):btn('change-plan','Change my plan',true)}${draft?btn('back-to-journey','Keep editing'):btn('export','Download Excel')}${btn('ask-adviser','Ask my adviser')}${draft?btn('cancel-draft','Cancel'):''}</div></section><section class="plan-at-a-glance"><div class="plan-direction"><span class="eyebrow">YOUR DIRECTION</span><p>${esc([plan.program.tracks.find(t=>t.id===plan.profile.track)?.name,plan.profile.secondTrack?plan.program.tracks.find(t=>t.id===plan.profile.secondTrack)?.name:null,plan.minor?.name?'Minor: '+plan.minor.name:null].filter(Boolean).join(' · ')||plan.program.name)}</p></div><div class="plan-progress"><strong>${completed} <span>/ ${total} credits</span></strong><p>Completed toward your plan</p><progress value="${completed}" max="${Math.max(1,total)}" aria-label="Completed credits"></progress></div></section>${draft&&plan.revisionAssessment?.delayed?`<p class="warning">This change moves your scheduled finish from ${esc(plan.revisionAssessment.before)} to ${esc(plan.revisionAssessment.after)}. Review the timing before saving.</p>`:''}${checks.length?`<div class="check-summary">${btn('checks',checks.length+' items to confirm')}<span>We’ll keep track of these alongside your plan.</span></div>`:''}${minorChecklistView(plan.profile,{plan:true})}<div class="semester-intro"><h2>Your semesters</h2><p class="small-note">Course targets: up to ${plan.profile.regularCourses} per regular semester${plan.profile.summers?' and '+plan.profile.summerCourses+' per summer session':'; no summer classes'}. Internship and prerequisite constraints still apply.</p><p class="small-note">Open a semester, then a course to record your progress.</p></div><div class="semester-grid">${plan.terms.map(t=>{const list=t.courses.map(id=>cs.find(c=>c.id===id));return `<details data-disclosure="semester-${esc(t.id)}" class="semester-card ${t.id==='pending'?'pending-card':''}" ${t.id===first||t.id==='pending'?'open':''}><summary class="semester-head"><div><h3>${label(t)}</h3><span class="semester-meta">${list.length} ${list.length===1?'course':'courses'}${list.length?' · '+list.filter(c=>done.includes(c.id)).length+' completed':''}</span></div><span class="credit-badge">${creditsOf(list)} credits</span></summary>${list.map(c=>`<button class="course ${done.includes(c.id)?'done':''}" data-course="${esc(c.id)}"><div><strong>${esc(c.title)}</strong><span>${esc(c.code||'Choice to confirm')} · ${c.credits} credits · ${esc(plan.tracking[c.id]?.status||'planned')}</span></div><span>${done.includes(c.id)?'✓':'›'}</span></button>`).join('')||'<p class="empty-term">No courses planned.</p>'}</details>`;}).join('')}</div>${roadmapInsights(plan)}${draft?'':`<details class="quiet-details"><summary>More plan options</summary><div class="card-actions">${btn('agent-replan','Course not offered? Ask my adviser')}${btn('mistake-report','Report an adviser mistake')}</div></details>`}`;
}

export function libraryView(view){if(view==='sources')return `<div class="view-intro"><h2>Your academic source library</h2><p>Read the supplied documents behind each requirement.</p></div><div class="panel source-list">${DATA.documents.map(d=>`<div><strong>${esc(d.file||d.filename||d.name)}</strong><span>${d.pages||d.pageCount||''} pages</span>${cite(d,'Read document')}</div>`).join('')}</div>`;
 if(view==='policies')return `<div class="view-intro"><h2>Rules and further study</h2><p>Policies guide planning; individual approvals and the applicable catalog still matter.</p></div>${[...DATA.policies,...GUIDED.policies].map(p=>`<article class="panel policy-card"><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p>${cite(p.source||p.sources?.[0])}</article>`).join('')}`;
 return `<div class="view-intro"><h2>Explore AUI programs</h2><p>Eight undergraduate and seven graduate roadmaps are modeled from your documents. </p></div><div class="program-grid">${DATA.programs.map(p=>`<article class="panel"><span class="tag">${p.level} · ${p.id}</span><h3>${esc(p.name)}</h3><p>${p.degreeCredits.min}–${p.degreeCredits.max} published credits</p>${cite(p.source)}${notes(p.notes)}${notes(p.conflicts)}</article>`).join('')}</div>`;}

export function planView(plan,draft){return basePlanView(plan,draft);}

export function minorChecklistView(profile,{editable=false,plan=false}={}){
 const m=minorSummary(profile);if(!m)return '';const courses=coursesFor(profile),count=`${m.selectedCourses} of ${m.requiredCourses} courses selected · ${m.selectedCredits} of at least ${m.requiredCredits} credits`;
 return `<details class="minor-checklist choice-group" data-disclosure="minor-checklist" ${editable?'open':''}><summary>${esc(m.name)} <span>${esc(count)}</span></summary><p class="small-note">${m.allSelected?'Every listed slot has a selected course.':'Your minor needs all '+m.requiredCourses+' requirements below. An open slot still needs a course; it is not completed credit.'}${m.approvalRequired?' Your school also needs to confirm this minor.':''} Supporting prerequisites are separate.</p>${m.reviewNote?`<p class="small-note">${esc(m.reviewNote)}</p>`:''}<ol class="minor-requirements">${m.rows.map(row=>{const c=courses.find(c=>c.id===row.id);return `<li>${editable&&row.choice&&!c.approvalOnly?choiceField(c,profile):plan?`<button class="text-button" data-course="${esc(row.id)}">${esc(row.code?row.code+' · '+row.title:row.title)}</button>`:`<strong>${esc(row.code?row.code+' · '+row.title:row.title)}</strong>`}<small>${row.credits} credits · ${row.selected?'Selected':row.approvalRequired?'Course needs school approval':'Course still to select'}</small>${row.reason?`<p class="small-note">${esc(row.reason)}</p>`:''}</li>`;}).join('')}</ol></details>`;
}
